<script setup lang="ts">
import {ref,computed} from 'vue'
import {Upload,RotateCcw,LoaderCircle} from 'lucide-vue-next'
const props=defineProps<{modelValue?:string;disabled?:boolean;name?:string}>(),emit=defineEmits<{'update:modelValue':[value:string];busy:[value:boolean]}>()
const reading=ref(false),error=ref(''),filename=ref('')
const preview=computed(()=>props.modelValue||'/site-icon/default')
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;error.value='';reading.value=true;emit('busy',true)
 try{const svg=file.name.toLowerCase().endsWith('.svg')||file.type==='image/svg+xml';if(!svg&&!file.name.toLowerCase().endsWith('.png')&&file.type!=='image/png')throw new Error('请选择 PNG 或 SVG 图标');if(file.size>(svg?20000:256*1024))throw new Error(svg?'SVG 图标不能超过 20 KB':'PNG 图标不能超过 256 KB');const bytes=new Uint8Array(await file.arrayBuffer());const value='data:'+(svg?'image/svg+xml':'image/png')+';base64,'+btoa(Array.from(bytes,byte=>String.fromCharCode(byte)).join(''));const image=new Image();await new Promise<void>((resolve,reject)=>{image.onload=()=>resolve();image.onerror=()=>reject(new Error('无法读取这个图标，请检查图片文件'));image.src=value});if(!svg&&(image.naturalWidth<16||image.naturalWidth>1024||image.naturalHeight<16||image.naturalHeight>1024))throw new Error('PNG 图标尺寸需为 16～1024 像素');emit('update:modelValue',value);filename.value=file.name}
 catch(e){error.value=(e as Error).message}finally{input.value='';reading.value=false;emit('busy',false)}
}
function reset(){emit('update:modelValue','');filename.value='';error.value=''}
</script>
<template><section class="site-icon-upload"><div><h3>站点图标</h3><p>用于浏览器标签页、登录页和顶部品牌标识。</p></div><div class="icon-upload-content"><img :src="preview" class="icon-preview-large" alt="站点图标预览"/><div class="icon-controls"><div class="icon-actions"><label class="btn secondary" :class="{disabled:disabled||reading}"><LoaderCircle v-if="reading" class="spinning" :size="16"/><Upload v-else :size="16"/>{{reading?'读取中…':'上传图标'}}<input type="file" accept=".png,.svg,image/png,image/svg+xml" :disabled="disabled||reading" @change="upload" aria-label="上传站点图标"/></label><button type="button" class="btn secondary" :disabled="disabled||reading||!modelValue" @click="reset"><RotateCcw :size="15"/>恢复默认图标</button></div><small>{{filename||(!modelValue?'当前使用星桥默认图标':'当前使用自定义图标')}} · 点击下方“保存配置”后生效</small></div></div><div class="favicon-preview"><img :src="preview" width="16" height="16" alt="标签页小图标预览"/><span>{{name||'星桥'}} · 标签页效果</span></div><p class="icon-help">支持 PNG（256 KB 以内，16～1024 像素）或静态 SVG（20 KB 以内），建议使用正方形图标。</p><p v-if="error" class="alert danger" role="alert">{{error}}</p></section></template>
<style scoped>.site-icon-upload{border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:26px}.site-icon-upload h3{margin:0 0 8px;font-size:15px}.site-icon-upload p{font-size:12px;color:var(--muted);line-height:1.8;margin:0}.icon-upload-content{display:flex;align-items:center;gap:18px;margin:20px 0}.icon-preview-large{width:64px;height:64px;object-fit:contain;border-radius:16px;flex-shrink:0;background:#f0f5f3}.icon-controls{min-width:0}.icon-actions{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:10px}.icon-actions label{display:inline-flex;flex-direction:row;position:relative;cursor:pointer;margin:0;font-weight:500}.icon-actions input{position:absolute;inset:0;opacity:0;width:100%;height:100%;margin:0;cursor:pointer}.icon-actions .disabled{opacity:.6;pointer-events:none}.icon-controls small{display:block;font-size:11px;color:var(--muted);overflow-wrap:anywhere}.favicon-preview{display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:9px 9px 0 0;padding:9px 12px;max-width:240px;background:#f5f8f7;font-size:12px;color:#4a615c}.favicon-preview img{object-fit:contain}.site-icon-upload .icon-help{margin-top:14px}.site-icon-upload .alert{margin-top:12px}@media(max-width:600px){.site-icon-upload{padding:16px}.icon-upload-content{align-items:flex-start;gap:12px}.icon-preview-large{width:48px;height:48px;border-radius:12px}.icon-actions .btn{font-size:11px;padding:9px 10px}}</style>
